def maxScore(n: int, k: int, stayScore: List[List[int]], travelScore: List[List[int]]) -> int:
    # dp[i] represents the max score ending at city i on the current day
    dp = [0] * n

    # Initial state: Day 0. The tourist can start at any city j and stay there.
    for j in range(n):
        dp[j] = stayScore[0][j]

    for i in range(1, k):
        next_dp = [0] * n
        # To optimize O(k*n^2) to O(k*n), we find the max of (dp[prev] + travelScore[prev][curr])
        # However, since stay and travel are independent options per day:
        # On day i, if at city 'j', score is dp_prev[j] + stayScore[i][j] 
        # OR max(dp_prev[p] + travelScore[p][j]) for all p != j.

        # Pre-calculate best possible transition from previous day to any city
        # Because n is small (200), O(k * n^2) is acceptable.
        for curr in range(n):
            best_prev = -float('inf')
            for prev in range(n):
                if prev == curr:
                    score = dp[prev] + stayScore[i][curr]
                else:
                    score = dp[prev] + travelScore[prev][curr]
                if score > best_prev:
                    best_prev = score
            next_dp[curr] = best_prev
        dp = next_dp

    return max(dp)
