def maxScore(nums: List[int]) -> int:
    def get_gcd(arr):
        if not arr:
            return 0
        res = arr[0]
        for x in arr[1:]:
            res = math.gcd(res, x)
        return res

    def get_lcm(arr):
        if not arr:
            return 0
        res = arr[0]
        for x in arr[1:]:
            # lcm(a, b) = (a * b) // gcd(a, b)
            res = (res * x) // math.gcd(res, x)
        return res

    def get_score(arr):
        if not arr:
            return 0
        g = get_gcd(arr)
        l = get_lcm(arr)
        return g * l

    n = len(nums)
    max_s = 0

    # Case: Remove zero elements
    max_s = max(max_s, get_score(nums))

    # Case: Remove exactly one element
    for i in range(n):
        sub = nums[:i] + nums[i+1:]
        if sub:
            max_s = max(max_s, get_score(sub))
        else:
            # If removing an element leaves an empty array, score is 0
            max_s = max(max_s, 0)

    return max_s
