def minValidStrings(words: List[str], target: str) -> int:
    # Build a Trie to store all words. 
    # Since any prefix of a word is valid, we just need to know if 
    # target[i:j] exists as a prefix of any word in 'words'.
    # A string x is a prefix of some word in 'words' iff it 
    # can be traversed in the Trie.
    trie = {}
    for word in words:
        node = trie
        for char in word:
            if char not in node:
                node[char] = {}
            node = node[char]

    n = len(target)
    # dp[i] is the minimum number of valid strings to form target[:i]
    # Initialize with infinity.
    dp = [float('inf')] * (n + 1)
    dp[0] = 0

    for i in range(n):
        if dp[i] == float('inf'):
            continue

        # From current position i, try to match the longest possible prefix
        node = trie
        for j in range(i, n):
            char = target[j]
            if char in node:
                node = node[char]
                dp[j + 1] = min(dp[j + 1], dp[i] + 1)
            else:
                # No more prefixes possible starting from i with this character
                break

    return int(dp[n]) if dp[n] != float('inf') else -1
