def maxSum(nums: List[int], k: int, m: int) -> int:
    n = len(nums)
    prefix_sum = [0] * (n + 1)
    for i in range(n):
        prefix_sum[i+1] = prefix_sum[i] + nums[i]

    # dp[i][j] is max sum of i subarrays using first j elements
    # Use float('-inf') for impossible states
    dp = [[float('-inf')] * (n + 1) for _ in range(k + 1)]
    for j in range(n + 1):
        dp[0][j] = 0

    for i in range(1, k + 1):
        # To optimize: dp[i][j] = max(dp[i-1][p] + (prefix_sum[j] - prefix_sum[p])) 
        # where j - p >= m. 
        # Rearrange: dp[i][j] = prefix_sum[j] + max(dp[i-1][p] - prefix_sum[p]) for p <= j - m
        max_prev = float('-inf')
        for j in range(m, n + 1):
            # Update the best possible previous split point
            # The new available split point is (j - m)
            prev_val = dp[i-1][j-m] - prefix_sum[j-m]
            if prev_val > max_prev:
                max_prev = prev_val

            # If we have a valid previous sum, update current dp
            if max_prev != float('-inf'):
                dp[i][j] = max(dp[i][j-1], prefix_sum[j] + max_prev)
            else:
                dp[i][j] = dp[i][j-1]

    return int(dp[k][n])
