            counts[q_tuple] = counts.get(q_tuple, 0) + 1

        unique_qs = []
        for q_tuple, count in counts.items():
            unique_qs.append((q_tuple, count))

        memo = {}

        def backtrack(u_idx: int, current_nums: tuple) -> bool:
            if u_idx == len(unique_qs):
                return all(x == 0 for x in current_nums)

            state = (u_idx, current_nums)
            if state in memo:
                return memo[state]

