                        if next_nums[idx] < v:
                            possible = False
                            break
                        next_nums[idx] -= v
                    if not possible: break

                if possible and backtrack(u_idx + 1, tuple(next_nums)):
                    memo[state] = True
                    return True

            memo[state] = False
            return False

        return backtrack(0, tuple(nums))

    # Binary search for the minimum k
    low = 0
    high = m
    ans = -1

