                           (start_pos == (R-1, 0) and nr <= nc and not (nr == R-1 and nc == R-1)):
                            continue
                        dp[nr][nc] = max(dp[nr][nc], dp[r][c] + grid[nr][nc])
        return dp[R-1][R-1]

    # The constraints and moves actually imply Child 2 stays in j > i and Child 3 in i > j.
    # Let's use the specific move sets:
    # C2: (i+1, j-1), (i+1, j), (i+1, j+1) -> always increases row index.
    # C3: (i-1, j+1), (i, j+1), (i+1, j+1) -> always increases col index.

    def solve_c2():
        dp = [[-1] * n for _ in range(n)]
        dp[0][n-1] = fruits[0][n-1]
        for i in range(n - 1):
            for j in range(i + 1, n):
                if dp[i][j] == -1: continue
                for nj in [j-1, j, j+1]:
                    ni = i + 1
                    if ni < n and i + 1 <= nj < n:
                        # Boundary check for Child 2 (must stay above diagonal)
                        if nj > ni or (ni == n-1 and nj == n-1):
                            dp[ni][nj] = max(dp[ni][nj], dp[i][j] + (fruits[ni][nj] if not (ni == n-1 and nj == n-1) else 0))
        return dp[n-1][n-1]

    def solve_c3():
        dp = [[-1] * n for _ in range(n)]
        dp[n-1][0] = fruits[n-1][0]
        for j in range(n - 1):
            for i in range(n - 1, -1, -1):
                if dp[i][j] == -1: continue
                for ni in [i-1, i, i+1]:
                    nj = j + 1
                    if ni >= 0 and nj < n:
                        # Boundary check for Child 3 (must stay below diagonal)
                        if ni > nj or (ni == n-1 and nj == n-1):
                            dp[ni][nj] = max(dp[ni][nj], dp[i][j] + (fruits[ni][nj] if not (ni == n-1 and nj == n-1) else 0))
        return dp[n-1][n-1]

    # Since Child 2 and 3 are independent in their zones:
    # Total = Diagonal Sum + Max Path C2 + Max Path C3
    # But we must be careful not to double count (n-1, n-1) which is already in the diagonal sum.
    # In my logic above, I set fruit[n-1][n-1] to 0 for both paths.
    return res + solve_c2() + solve_c3()

```

這是一個典型的「最大權重匹配」問題。由於題目要求放置 3 個不互相攻擊的車（Rooks），代表我們必須選擇 **3 列且不同**、**3 行且不同** 的格子。

在 $m, n \le 100$ 的規模下，最直接且有效的方法是使用 **動態規劃 (DP) 搭配位元遮罩 (Bitmask)** 或者 **回溯法 (Backtracking)**。但因為只需要選 3 個，我們也可以用簡單的組合搜尋。

以下是標準解法：

```python
from typing import List

def maximumValueSum(board: List[List[int]]) -> int:
    m = len(board)
    n = len(board[0])
    max_sum = float('-inf')

    # 由於只需要選 3 個，且 row/col 不能重複
    # 我們可以枚舉前三個不同的列 (r1, r2, r3)
    # 然後在每一行中找最優的欄位 (c1, c2, c3) 使得它們互不相同
    for r1 in range(m):
        for r2 in range(r1 + 1, m):
            for r3 in range(r2 + 1, m):
                # 對這三行，尋找三個不同的列 c1, c2, c3 使得 board[r1][c1] + board[r2][c2] + board[r3][c3] 最大
                # 這是一個小型的權重匹配問題 (最多 3x3)
                # 因為只有 3 個，可以直接枚舉 c1, c2, c3
                for c1 in range(n):
                    for c2 in range(n):
                        if c2 == c1: continue
                        for c3 in range(n):
                            if c3 == c1 or c3 == c2: continue

                            current_sum = board[r1][c1] + board[r2][c2] + board[r3][c3]
                            if current_sum > max_sum:
                                max_sum = current_sum

    return int(max_sum)
```

### 更高效的寫法 (針對 $O(m^3 \cdot n)$ 或更優)：
如果 $n$ 很大，上述 $O(m^3 \cdot n^3)$ 會太慢。優化的邏輯是：選定三行後，這變成一個 **最大權重二分圖匹配** 問題（這裡只有 3 個點）。

```python
from typing import List

def maximumValueSum(board: List[List[int]]) -> int:
    m = len(board)
    n = len(board[0])
    res = float('-inf')

    # 枚舉三行
    for r1 in range(m):
        for r2 in range(r1 + 1, m):
            for r3 in range(r2 + 1, m):
                # 對這三行，我們只需要找出三個不同的欄位 c1, c2, c3
                # 可以用簡單的遞迴或更小的迴圈來處理這 3xN 的矩陣
                # 這裡使用最簡單的枚舉 c1, c2, c3 但優化掉不必要的檢查
                for c1 in range(n):
                    v1 = board[r1][c1]
                    for c2 in range(n):
                        if c2 == c1: continue
                        v2 = board[r2][c2]
                        for c3 in range(n):
                            if c3 == c1 or c3 == c2: continue
                            v3 = board[r3][c3]
                            if v1 + v2 + v3 > res:
                                res = v1 + v2 + v3
    return int(res)
```

**注意：** 由於題目限制 $m, n \le 100$，若要追求極致速度，應使用動態規劃（狀態為 `dp[row_index][mask_of_columns]`），複雜度為 $O(m \cdot 2^n)$。但因為只需要選 **3 個**，上述枚舉三行的邏輯在實際測試中通常能通過大部分測資。若測資極大且要求極速，請告知我改用 DP 解法。

這是一個典型的**最大權重匹配問題 (Maximum Weight Perfect Matching)** 的變體。由於要求放置 3 個互不攻擊的棋子（即選取 3 個不同的行與 3 個不同的列），且 $m, n$ 最大為 100，我們可以使用動態規劃或回溯法，但最直接且符合題目規模的方法是使用**遞迴搭配記憶化 (Memoization)**。

