            return 0

        state = (row_idx, col_mask)
        if state in memo:
            return memo[state]

        # 選項 1：不放棋子在這一行（僅當剩餘行數足夠放 3 個時才考慮，但為了簡化可直接跳過）
        res = solve(row_idx + 1, col_mask)

        # 選項 2：嘗試在這一行的每一列放棋子
        for j in range(n):
            if not (col_mask & (1 << j)):
                res = max(res, board[row_idx][j] + solve(row_idx + 1, col_mask | (1 << j)))

        memo[state] = res
        return res

