    # 這裡提供一個最通用的解法（針對 m, n <= 100）：

    memo = {}
    def dfs(r_idx, current_mask):
        if bin(current_mask).count('1') == 3:
            return 0
        if r_idx >= m:
            return float('-inf')

        state = (r_idx, current_mask)
        if state in memo: return memo[state]

        # 不選這一行
        res = dfs(r_idx + 1, current_mask)

        # 選這一行的某一列
