                val = dfs(r_idx + 1, current_mask | (1 << c))
                if val != float('-inf'):
                    res = max(res, board[r_idx][c] + val)

        memo[state] = res
        return res

    # 由於 n 可能到 100，bitmask 不適用。改用簡單的遞迴選取 3 行與 3 列：
    # 因為只需 3 個，我們可以用三層迴圈選行，再處理列匹配（或反過來）

    ans = float('-inf')
    # 為了保證速度，若 m, n 很大，這題實際上是找最大權重的不相交子集。
    # 這裡使用最直接的遞迴 + 剪枝：
    memo_simple = {}
    def solve_fast(r_idx, used_cols):
        if len(used_cols) == 3:
            return 0
        if r_idx >= m:
            return float('-inf')

        state = (r_idx, tuple(sorted(used_cols)))
        if state in memo_simple: return memo_simple[state]

        # 不選這一行
        res = solve_fast(r_idx + 1, used_cols)

        # 選這一行的某一列
        for c in range(n):
            if c not in used_cols:
                val = solve_fast(r_idx + 1, used_cols | {c})
                if val != float('-inf'):
