        memo_simple[state] = res
        return res

    # 考慮到 m, n <= 100，且只需要選3個，最快的方式是：
    # 選取 3 個不同的行 i1, i2, i3 和 3 個不同的列 j1, j2, j3
    # 這樣複雜度是 C(m,3) * C(n,3) * 3! (約為 100^6，略大但可行)
    # 但其實可以用 DP: dp[i][j] 表示前 i 行選了 j 個棋子且不衝突的最大和。
    # 因為列的限制較複雜，我們用最簡單的 DFS 並限制深度。

    # 最終採用最符合題意的實作：
    memo = {}
    def final_dfs(r, count, mask): # mask 用於記錄選過的列 (這裡用 set 模擬)
        if count == 3: return 0
        if r >= m: return float('-inf')
        state = (r, count, tuple(sorted(mask)))
        if state in memo: return memo[state]

        res = final_dfs(r + 1, count, mask) # 不選這一行
        for c in range(n):
            if c not in mask:
                sub = final_dfs(r + 1, count + 1, mask | {c})
                if sub != float('-inf'):
                    res = max(res, board[r][c] + sub)
        memo[state] = res
        return res

    # 為了避免超過遞迴深度與時間，針對 m=100 且只選3個，其實可以直接用三層迴圈找最大值。
    # 但最標準的解法是：
