                pass # 此處邏輯簡化

    # 正確且快速的實作：使用遞迴選取 3 個位置，確保行與列不重複。
    memo = {}
    def dfs_fixed(r, current_cols):
        if len(current_cols) == 3: return 0
        if r >= m: return float('-inf')
        state = (r, tuple(sorted(current_cols)))
        if state in memo: return memo[state]

        res = dfs_fixed(r + 1, current_cols)
        for c in range(n):
