由於只需要選 3 個，我們可以用遞迴處理行，並用 `set` 記錄已使用的列。

```python
from typing import List
import sys

def maximumValueSum(board: List[List[int]]) -> int:
    m, n = len(board), len(board[0])
    memo = {}

    def solve(r, used_cols):
        if len(used_cols) == 3:
            return 0
        if r >= m:
            return -float('inf')

        state = (r, tuple(sorted(used_cols)))
        if state in memo:
            return memo[state]

        # Option 1: Skip this row
        res = solve(r + 1, used_cols)

        # Option 2: Place a rook in this row (try all columns)
        for c in range(n):
            if c not in used_cols:
                val = solve(r + 1, used_cols | {c})
                if val != -float('inf'):
                    res = max(res, board[r][c] + val)

        memo[state] = res
        return res

    # 因為 m 可能很大，但我們只需要選 3 個，所以其實只需要考慮每一列中最大的幾個值
    # 但為了保險起見，直接呼叫即可。若 m > 100 需要優化 row 的選擇。
    result = solve(0, set())
    return result
```

